head.script:
scwin.gVar = {
    "cRef" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > P > ref]<br/>Textarea 컴포넌트의 입력값에 바인딩할 DataCollection 정보를 설정합니다.",
    "validation" : [
        "접근 가능한 DataCollection 의 컬럼을 'data:[DataCollection ID].[Key 또는 Column ID]' 형식으로 설정합니다.",
        "유효하지 않은 값으로 설정 시 바인딩 처리되지 않고 입력창에 빈값이 표시됩니다.",
        "DataList 를 바인딩 한 경우 DataList 의 데이터를 선택하지 않으면 입력창에 빈값이 표시됩니다.",
        "데이터를 선택하지 않은 상태에서 입력된 값은 데이터 선택 시 사라집니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 공통 wframe 의 btn_getText_onclick 은 textarea 의 render.textContent 를 읽어 입력값을 못 가져옴
    // → textarea 의 getValue() API 를 사용하도록 override
    wf_sample.getObj("scwin").btn_getText_onclick = function () {
        wf_sample.getObj("wf_body_bottom").getObj("scwin").setReturnValue("text : " + target1.getValue());
    };
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (style 은 strTarget 에서 직접 정의 → 중복 정의 금지)
    let properties = {
        ref: scwin.gVar["cRef"],
    };

    let cList = $c.gcm.createCList(properties);

    // empty textarea 동적 생성 (createBasicTextArea 는 기본값을 설정하므로 ref 바인딩 테스트에는 비어있는 textarea 사용)
    let grp_comp = $c.gcm.getTestGroup('');

    let strTarget = '<xf:textarea ' + $c.gcm.strNameSpace + ' ' + cList + ' id="" style="width:300px; height:100px;"></xf:textarea>';

    scwin.target1 = await $p.dynamicCreate(
        'target1',
        'textarea',
        strTarget,
        grp_comp
    );
}
